"""Editorial teaching specifications. Original textbook data stays in curriculum/lessons.json."""
from scripts.build_adaptations import q, task, refs, prototype

def pattern(n,key,title,explanation,examples,slides,pitfall,application):
 return {'id':f'zt-{n:02d}-pattern-{key}','title':title,'explanation':explanation,'examples':examples,'sourceRefs':refs(n,*slides),'origin':'adaptation','exampleOrigin':'textbook','pitfall':pitfall,'application':application}

def unit(n,subtitle,readings,grammar,topic,diagnostic,patterns,questions,discussions,analysis,writing,speaking,extension,culture='',exercise_slides=()):
 # analysis = prompt, model, checks; writing/speaking = title, prompt, model, checks, scaffold
 allrefs=sorted(set(readings+grammar+list(exercise_slides)))
 tasks=[task(n,'interpretation','Interpret with evidence',analysis[0],analysis[1],readings,minimum=70,criteria=['comprehension','organization','intercultural'] if n>=16 else ['comprehension','accuracy','organization'],checks=analysis[2],scaffold=['Quote a short source phrase, then explain what it shows.','Separate a statement from an inference or an unanswered question.'],challenge=extension)]
 tasks.append(task(n,'writing',writing[0],writing[1],writing[2],allrefs,minimum=160,checks=writing[3],scaffold=writing[4],challenge=extension,criteria=['comprehension','accuracy','communication','organization','audience']+(['intercultural'] if n>=16 else [])))
 tasks.append(task(n,'roleplay',speaking[0],speaking[1]+' Perform for 2–3 minutes, then switch roles. In round two introduce the changed constraint. Save an 80–140-character transcript excerpt or reflection. A partner or teacher supplies live listening; the app does not record speech or assess pronunciation.',speaking[2],readings,kind='roleplay',minimum=80,checks=speaking[3],scaffold=speaking[4],challenge=extension,criteria=['accuracy','communication','audience']+(['intercultural'] if n>=16 else [])))
 return {'id':f'zt-{n:02d}','subtitle':subtitle,'minutes':65 if n<16 else 70,'readingSlides':readings,'readingPrompts':{str(s):[{'prompt':a,'guide':b} for a,b in pairs] for s,pairs in discussions.items()},'objectives':[f'Interpret source evidence in {subtitle.lower()}, including what remains unstated.',f'Use {"; ".join(p["title"] for p in patterns)} in connected Chinese.',writing[3][0],speaking[3][0]],'goals':[analysis[2][0],speaking[3][0],writing[3][0]],'hospitality':topic,'patterns':patterns,'questions':questions,'tasks':tasks,'culturalNotes':[{'id':f'zt-{n:02d}-context','title':'Source context & editorial judgement','text':culture or 'The dialogue is a course scenario. New activities and models extend its language; they do not add facts to the original textbook. Interpret the situation before adapting the wording.','origin':'supplementary','sourceRefs':refs(n,*allrefs)}],'pedagogy':{'profile':'Read the original Chinese first. Skip pinyin unless useful; invest effort in inference, coherent responses and audience. Use the speaking round to diagnose fluency separately from reading.','diagnostic':diagnostic,'sequence':[{'stage':'Understand','minutes':20,'activity':analysis[2][0]},{'stage':'Communicate','minutes':20,'activity':speaking[3][0]},{'stage':'Apply professionally','minutes':25 if n<16 else 30,'activity':writing[3][0]}],'decisions':[{'action':'retain','content':'Original dialogues, the complete source word lists, central patterns and cultural material remain accessible in their original sequence.','sourceRefs':refs(n,*readings)},{'action':'extend','content':analysis[0],'sourceRefs':refs(n,*readings)},{'action':'scaffold','content':'Optional source Thai/pinyin, contextual chunks and task-specific sentence openings; spoken and written performance receive separate teacher feedback.','sourceRefs':refs(n,*grammar)},{'action':'interactive','content':'New evidence, vocabulary, grammar and communication checks have independent authored answer keys. Original exercise displays are retained; unverified answer-to-blank mappings are not auto-scored.','sourceRefs':refs(n,*(list(exercise_slides) or grammar))}],'multilingual':'Optional: compare one useful expression with Thai, German, English or Dutch. Explain a difference in word order or register, then return to Chinese. Your languages are resources, not translation homework.','reflection':'Which task-specific criterion improved after revision? Quote a Chinese phrase, identify one remaining difficulty, and choose a next practice step.'}}

def first_half():
 u=[];n=1
 u.append(unit(n,'Arrival & a helpful first response',[6,10,14],[3,4,5,15,16],
 'Airport reception and meeting-point clarification. Practise orientation and courteous requests; current visa eligibility or procedures are outside this language brief.',
 'Explain the difference between 我到泰国啦 and 我马上到机场. Then give an arrival update without translating each word.',[
 pattern(n,'degree','太…了 / 不太…','太 + adjective + 了 expresses a strong reaction here. 不太 + adjective softens a negative assessment; the source examples do not add this final 了.',['手机太方便了！','学校离家不太远。'],[15,16],'不太远 is not the same as 很近; it softens the negative without giving a precise distance.','Give an enthusiastic personal reaction, then a measured service description.'),
 pattern(n,'arrival','到 / 马上 / 等一下','到 reports reaching a place; 马上 places an event in the near future in these examples. Wait expressions manage the interaction rather than promise a precise number of minutes.',['我马上到机场了。','请稍等，我马上来。'],[4,5],'我马上到 does not mean I am already there. Do not invent a precise wait time.','Send an arrival update and one polite waiting request.')], [
 q(n,'location','At the end of dialogue one, where does 小爱 say she will wait?',['在机场。','在酒店。','在银行。'],'She says 我在机场等你; 佳佳 is still going to the airport.',[6]),
 q(n,'inference','Which detail does 不太远 leave unresolved?',['具体距离和走法。','柜台在那里。','工作人员已经回答问题。'],'不太远 evaluates distance but gives no route or measurement.',[10]),
 q(n,'documents','Which documents does the officer request in this textbook exchange?',['护照和登机牌。','房卡和菜单。','银行卡和门票。'],'请给我护照和登机牌 is the source line. This is retrieval from a dialogue, not a current document checklist.',[14]),
 q(n,'wait','Complete with the two-character source wait expression: 请____，我马上来。',None,'稍等 is the polite brief-wait expression on slide 5. It does not specify a duration.',[5],'accuracy',answers=['稍等'],category='vocabulary'),
 q(n,'process','Which source collocation means to complete arrival-visa formalities?',['办落地签','坐落地签','穿落地签'],'办 collocates with formalities such as 办护照 and 办落地签 on slide 8.',[8],'accuracy',category='vocabulary'),
 q(n,'soften','Use the source softening pattern: 不____远。（one character）',None,'不太远 softens a negative assessment. 太 goes between 不 and the adjective in this pattern.',[16],'accuracy',answers=['太'],category='grammar'),
 q(n,'timeline','Which update indicates arrival is imminent rather than completed?',['我马上到机场。','我已经到机场了。','我现在在机场等你。'],'马上 marks an imminent event here; the other two place the speaker at the airport.',[4,6],'accuracy',category='grammar'),
 q(n,'repair','A visitor hears “在那儿” but still looks unsure. Which follow-up advances communication?',['请问您看见那个柜台了吗？我再说明一下方向。','不太远，所以不用再问。','落地签一定适合每位游客。'],'Clarify the reference point. Do not turn the source language exchange into eligibility advice.',[10],'communication','apply')],
 {6:[('Who has arrived, and who is still travelling? Cite evidence.','小爱 has reached Thailand; 佳佳 says 我马上到机场. Do not merge their timelines.')],10:[('What further information would make 在那儿 useful?','A shared visible reference point or route clarification. The dialogue alone does not supply a full route.')],14:[('Which lines show request, completion and welcome?','请给我… is a request; 可以了 marks completion in this exchange; 欢迎您 welcomes the visitor.')]},
 ('In 70–110 Chinese characters, compare the two speakers’ locations and timing in dialogue one. Explain why 马上 cannot be treated as 已经.','小爱说“我到泰国啦”，说明她已经到达。佳佳说“我马上到机场”，说明她还在去机场的途中。小爱会在机场等她。因此，“马上”表示很快会发生，不能据此说佳佳已经到了机场。',['Distinguish completed arrival from an imminent arrival.','Support the timeline with two quotations.']),
 ('An airport meeting message','Write 160–240 Chinese characters to a visitor whose exact meeting point is unclear. Welcome them, explain which source speaker has arrived, ask for a visible landmark, state where to wait after mutual confirmation, and explain how you will update them. Use 请问, 等 and 马上 appropriately. Do not invent a real airport route.','您好，欢迎您来泰国！您说已经到机场了，我想先确认一下您现在的位置。请问您能看见哪个柜台，或者附近有什么明显的标志？您可以把标志的文字告诉我，我们再一起确认见面的地方。确认以后，请您在约定的地点稍等。如果我说“马上到”，意思是我还在路上，并不是已经站在您的旁边。到达后我会再给您消息；如果位置有变化，也请告诉我。这样我们就不会因为“在那儿”不够清楚而走错地方。',['Clarify a meeting point without inventing a route.','Use time expressions accurately.','Close with a clear next action.'],['您好，欢迎…；请问您现在…？','我马上…；确认以后，请…']),
 ('Find each other at arrivals','Visitor: you have arrived but cannot identify the meeting point. Host: you are still travelling and must clarify a shared landmark. Round two: the visitor moves to another location.','客人：我已经到机场了，可是不知道在哪儿等。\n接待人：请问您附近有什么标志？我还在路上，到达以后再联系您。\n客人：我换了一个地方。\n接待人：好的，请先告诉我新的位置，我们再确认。',['Resolve an unclear location through follow-up questions.','Paraphrase the final meeting agreement.'],['Visitor: share location only after being asked.','Host: distinguish arrived / imminent; repeat the agreed point.']),
 'Write a 300–400-character arrival communication plan with a missed-meeting contingency. Justify how your wording avoids false reassurance.',
 'Visa dialogue facts remain historical source context. Do not use them as current entry guidance. The new activities focus on communication, not legal eligibility.'))
 n=2
 u.append(unit(n,'Places, perspectives & a shared itinerary',[5,8,11],[7,10,12],
 'Destination enquiry and a concise visitor itinerary. Clarify places and interests before proposing an order.',
 'Explain 来 versus 去 from the speaker’s location, then list the places the visitors have actually visited.',[
 pattern(n,'motion','来 / 去','The source contrasts movement toward a speaker/reference point (来) with movement away (去). The same trip can be described differently by speakers at different locations.',['欢迎你来泰国！','我想去清迈。'],[12],'Do not choose the verb solely from an English translation; establish the reference point.','Describe the same trip as visitor and host.'),
 pattern(n,'distance','A 离 B 远 / 近','离 relates two places in a distance description. State the reference places explicitly when the listener cannot infer them.',['大皇宫离你的酒店不远。'],[7,8],'不远 is not a measured route or a promise of a short journey.','Explain a relative location, then ask for the actual starting point.'),
 pattern(n,'list','都 + question word','In the source’s questions, 都 invites a fuller list of experiences or places. It does not simply mean every person in every use.',['你们都去哪儿玩了？'],[10],'Keep the question word; a complete answer should respond to the requested list.','Interview a partner about places visited and summarize the list.')],[
 q(n,'places','Which list matches 小爱’s interests in dialogue one?',['大皇宫、卧佛寺、安帕瓦水上市场。','机场、银行、商场。','查龙寺、苏梅岛、拉威海滩。'],'These three places are named on slide 5.',[5]),
 q(n,'correction','What mistaken identification is corrected?',['把卧佛寺认成大皇宫。','把机场认成酒店。','把水上市场认成学校。'],'那儿不是大皇宫，那儿是卧佛寺 corrects the identification.',[8]),
 q(n,'duration','How long does 小爱 say she has been in Bangkok?',['三天。','三个月。','课文没有提到。'],'我来曼谷三天了 explicitly states three days.',[11]),
 q(n,'additional','Complete the source addition: 我想去大皇宫、卧佛寺，____想去安帕瓦水上市场。',None,'还 adds a further wish rather than replacing the earlier places.',[5],'accuracy',answers=['还'],category='vocabulary'),
 q(n,'distance-word','Complete: 大皇宫____你的酒店不远。',None,'离 links the two locations in the distance relation.',[7,8],'accuracy',answers=['离'],category='grammar'),
 q(n,'perspective','A host in Thailand invites someone abroad. Choose the source-consistent wording.',['欢迎你来泰国！','欢迎你去泰国！','欢迎你离泰国！'],'来 fits movement toward the host’s reference point.',[12],'accuracy',category='grammar'),
 q(n,'full-list','What does 都 contribute in 你们都去哪儿玩了？',['邀请对方列出游览过的地方。','只允许说一个地方。','表示所有地方都一样。'],'The source explains a follow-up enquiry asking for a fuller list.',[10],'accuracy',category='vocabulary'),
 q(n,'clarify','A visitor points at a building and asks whether it is the Grand Palace. Which reply best follows the source repair?',['那儿是卧佛寺。您想先去哪个地方？','都差不多，不必区分。','您一定想去全部景点。'],'Correct the identification, then ask rather than assume the intended destination.',[8],'communication','apply')],
 {5:[('Which places are desired rather than already visited?','想 marks wishes in dialogue one; dialogue three reports later visits.')],8:[('How does the correction avoid agreeing with a false identification?','不是…，是… names the correct place directly.')],11:[('How does the question with 都 shape the reply?','It prompts a list; 小爱 names all three places rather than a yes/no answer.')]},
 ('In 70–110 Chinese characters, contrast 小爱’s intentions in slide 5 with her later report in slide 11. Quote a marker of each.','第五页的小爱说“我想去”，是在表达愿望，不能说明已经去过。第十一页她说“我们去了”，是在回顾三天里的活动。两段都提到大皇宫、卧佛寺和安帕瓦水上市场，但是时间和交际目的不同。',['Distinguish intended and reported visits.','Use textual evidence rather than a guessed chronology.']),
 ('A destination enquiry reply','Write 160–240 Chinese characters to a visitor considering the three source destinations. Ask about interests and time, clarify the difference between two places, use one 离 sentence explicitly framed as the source situation, and propose how to choose an itinerary.','您好！您想去大皇宫、卧佛寺，还是安帕瓦水上市场？这三个地方都出现在课文里，但大皇宫和卧佛寺并不是同一个地方。请问您更想了解建筑，还是逛市场、看看当地生活？您明天有多少时间，也希望留多少休息时间？课文说大皇宫离客人的酒店不远，但您的出发地点可能不同。我们可以先确认酒店位置和您的兴趣，再核实路线与开放安排。请把最想去的地方告诉我，我再整理一个方便您比较的行程建议。',['Ask for interests before ordering an itinerary.','Distinguish destinations correctly.','Explain a source distance without turning it into a live promise.'],['您想…，还是…？','不是…，是…；…离…','先确认…，再…']),
 ('Correct a destination misunderstanding','Visitor: mistake Wat Pho for the Grand Palace and initially want all three destinations. Adviser: correct politely and ask about available time. Round two: the visitor has only half a day.','游客：那儿是大皇宫吗？\n顾问：那儿是卧佛寺。您今天都想去哪些地方？\n游客：三个都想去，可是只有半天。\n顾问：那我们先选您最感兴趣的一个，再确认安排。',['Correct and narrow a plan through questions.','Summarize a revised preference.'],['Visitor: name interests, then reduce available time.','Adviser: correct → enquire → prioritize.']),
 'Prepare a 300–400-character proposal comparing two possible visit orders. Mark any travel times you would need to verify.',exercise_slides=[10]))
